1	/**
2	 * doc-links.test.ts — every relative link and anchor between documents resolves.
3	 *
4	 * ## The failure this exists for
5	 *
6	 * `docs/` is about to be split from six flat files into a tree, and the first
7	 * measurement of that split was that ninety-five links run between these documents.
8	 * Roughly half name a file and half name a heading inside one. A move breaks them
9	 * all at once, and a broken link in Markdown is silent: GitHub renders it, it looks
10	 * like a link, and it 404s only for the reader who follows it.
11	 *
12	 * That is exactly the failure the documentation issue was opened for — a document
13	 * that goes stale with nothing saying so — which makes a split performed without
14	 * this test an instance of the disease it is meant to cure.
15	 *
16	 * ## What it does not check
17	 *
18	 * Absolute URLs. A link to `https://github.com/...` may rot, and asking the network
19	 * would make this test slow and flaky in equal measure. Nothing here leaves the
20	 * repository.
21	 *
22	 * Nor does it check that a link is the RIGHT one: a link to an existing heading
23	 * that answers a different question passes. Only that what it names is there.
24	 */
25	import { describe, expect, test } from "bun:test";
26	import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
27	import { dirname, join, relative, resolve } from "node:path";
28	
29	/** Every Markdown file this repository is the author of. */
30	function markdownFiles(): string[] {
31	  const roots = ["docs", "src/content", "self", ".github/atomaton"];
32	  const found: string[] = [];
33	  const walk = (dir: string) => {
34	    if (!existsSync(dir)) return;
35	    for (const entry of readdirSync(dir)) {
36	      if (entry === "node_modules") continue;
37	      const path = join(dir, entry);
38	      if (statSync(path).isDirectory()) walk(path);
39	      else if (entry.endsWith(".md")) found.push(path);
40	    }
41	  };
42	  for (const root of roots) walk(root);
43	  for (const name of ["README.md", "CONTRIBUTING.md"]) if (existsSync(name)) found.push(name);
44	  return found;
45	}
46	
47	/**
48	 * The link targets in one file, as written.
49	 *
50	 * Inline links only — `[text](target)`. Reference-style definitions are not used
51	 * anywhere in this repository, and a pattern for a form nobody writes is a pattern
52	 * nobody maintains.
53	 *
54	 * Fenced code is stripped first. A README that SHOWS a Markdown link as an example
55	 * is not claiming the target exists, and a test that reads an example as a claim is
56	 * one nobody can satisfy.
57	 */
58	function linksIn(source: string): string[] {
59	  const prose = source.replace(/```[\s\S]*?```/g, "").replace(/`[^`\n]*`/g, "");
60	  return [...prose.matchAll(/\[[^\]]*\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g)].map((m) => m[1] ?? "");
61	}
62	
63	/**
64	 * A heading's anchor, as GitHub derives it: lowercased, punctuation dropped, spaces
65	 * to hyphens. Close enough for the headings this repository writes, and a heading
66	 * exotic enough to defeat it is one worth rewording rather than encoding for.
67	 *
68	 * `_` is kept, and that is not a detail. GitHub's slugger keeps it, and most
69	 * configuration keys carry one -- `setup_commands`, `max_reloads`,
70	 * `from_pull_request`, `governed_paths`. Dropping it here would have made every
71	 * anchor in the key index either fail this test or 404 on GitHub, with no spelling
72	 * that satisfies both.
73	 */
74	function anchorsIn(source: string): Set<string> {
75	  const prose = source.replace(/```[\s\S]*?```/g, "");
76	  const anchors = new Set<string>();
77	  for (const [, hashes, text] of prose.matchAll(/^(#{1,6})\s+(.+?)\s*$/gm)) {
78	    void hashes;
79	    const slug = (text ?? "")
80	      .replace(/`/g, "")
81	      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
82	      .toLowerCase()
83	      .replace(/[^\p{L}\p{N}\s_-]/gu, "")
84	      .trim()
85	      .replace(/\s+/g, "-");
86	    if (slug) anchors.add(slug);
87	  }
88	  return anchors;
89	}
90	
91	const files = markdownFiles();
92	
93	describe("the links between this repository's documents", () => {
94	  test("there are documents to check", () => {
95	    expect(files.length).toBeGreaterThan(5);
96	  });
97	
98	  test.each(files)("%s names nothing that is not there", (file) => {
99	    const source = readFileSync(file, "utf8");
100	    const broken: string[] = [];
101	
102	    for (const target of linksIn(source)) {
103	      // Anything addressed to the outside is somebody else's to keep true.
104	      if (/^(https?:|mailto:|#)/.test(target)) {
105	        if (target.startsWith("#")) {
106	          const anchor = target.slice(1).toLowerCase();
107	          if (!anchorsIn(source).has(anchor)) broken.push(`${target} (no such heading in this file)`);
108	        }
109	        continue;
110	      }
111	
112	      const [pathPart = "", anchor] = target.split("#");
113	      const resolved = resolve(dirname(file), pathPart);
114	      if (!existsSync(resolved)) {
115	        broken.push(`${target} (no file at ${relative(".", resolved).replace(/\\/g, "/")})`);
116	        continue;
117	      }
118	      if (anchor && resolved.endsWith(".md")) {
119	        const anchors = anchorsIn(readFileSync(resolved, "utf8"));
120	        if (!anchors.has(anchor.toLowerCase())) broken.push(`${target} (no such heading)`);
121	      }
122	    }
123	
124	    expect(broken, `${file} links to:\n  ${broken.join("\n  ")}`).toEqual([]);
125	  });
126	});
127	
128	/**
129	 * Reachability, which is a different question from whether a link resolves.
130	 *
131	 * The move that this file was written to guard did not break one link. It deleted
132	 * `recipes.md`, whose Contents table was the only thing that named the eighteen
133	 * recipes -- and eleven of the files it became were then reachable from nowhere. Every
134	 * link in the repository still pointed at something real. The test above passed.
135	 *
136	 * A document nothing links to is one you find by knowing it is there, which is the
137	 * state the documentation issue was opened about.
138	 */
139	describe("every document under docs/ can be reached from another one", () => {
140	  /** `docs/README.md` is the map. It is reached from the repository's own README. */
141	  const MAP = "docs/README.md";
142	
143	  test("nothing under docs/ is orphaned", () => {
144	    const linked = new Set<string>();
145	    for (const file of files) {
146	      const source = readFileSync(file, "utf8");
147	      for (const target of linksIn(source)) {
148	        if (/^(https?:|mailto:|#)/.test(target)) continue;
149	        const resolved = resolve(dirname(file), target.split("#")[0] ?? "");
150	        // Relative to the repository, and with the separators git uses, so the
151	        // comparison does not depend on which platform ran the test.
152	        linked.add(relative(".", resolved).split("\\").join("/"));
153	      }
154	    }
155	
156	    const orphans = files
157	      .map((f) => f.split("\\").join("/"))
158	      .filter((f) => f.startsWith("docs/"))
159	      .filter((f) => f !== MAP)
160	      .filter((f) => !linked.has(f));
161	
162	    expect(
163	      orphans,
164	      "these are reachable only by knowing they exist. Name them from " +
165	        `${MAP}, or from the document whose subject they belong to:\n  ` +
166	        orphans.join("\n  "),
167	    ).toEqual([]);
168	  });
169	
170	  test("the map itself is reached from the repository's README", () => {
171	    const readme = readFileSync("README.md", "utf8");
172	    const targets = linksIn(readme).map((t) => t.split("#")[0]);
173	    expect(targets, `README.md does not link to ${MAP}, so nothing reaches the map`).toContain(MAP);
174	  });
175	});
